CALLS = [{"name": "bash", "arguments": {"command": "cat > paasio.py <<'PY'\nimport io\nclass MeteredFile(io.BufferedRandom):\n def __init__(self,*a,**k):\n  super().__init__(*a,**k);self._rb=self._ro=self._wb=self._wo=0\n def __enter__(self): return self\n def __exit__(self,*a): return super().__exit__(*a)\n def __iter__(self): return self\n def __next__(self):\n  d=super().readline()\n  if not d: raise StopIteration\n  self._ro+=1;self._rb+=len(d);return d\n def read(self,size=-1):\n  d=super().read(size);self._ro+=1;self._rb+=len(d);return d\n @property\n def read_bytes(self): return self._rb\n @property\n def read_ops(self): return self._ro\n def write(self,b):\n  n=super().write(b);self._wo+=1;self._wb+=n;return n\n @property\n def write_bytes(self): return self._wb\n @property\n def write_ops(self): return self._wo\nclass MeteredSocket:\n def __init__(self,socket): self.socket=socket;self._rb=self._ro=self._sb=self._so=0\n def __enter__(self): self.socket.__enter__();return self\n def __exit__(self,*a): return self.socket.__exit__(*a)\n def recv(self,bufsize,flags=0):\n  d=self.socket.recv(bufsize,flags);self._ro+=1;self._rb+=len(d);return d\n @property\n def recv_bytes(self): return self._rb\n @property\n def recv_ops(self): return self._ro\n def send(self,data,flags=0):\n  n=self.socket.send(data,flags);self._so+=1;self._sb+=n;return n\n @property\n def send_bytes(self): return self._sb\n @property\n def send_ops(self): return self._so\nPY\npython3 -m py_compile paasio.py", "timeout": 30}}]
